pub struct Queue<T> { inner: Mutex<Inner<T>>, space: Condvar, cap: usize }
struct Inner<T> { buf: VecDeque<T> }
impl<T> Queue<T> {
    pub fn put(&self, item: T) {
        let mut g = self.inner.lock().unwrap();
        g = self.space.wait_while(g, |i| i.buf.len() == self.cap).unwrap();
        g.buf.push_back(item);
    }
}

