struct Queue<T> { inner: Arc<Mutex<Inner<T>>>, room: Notify }

impl<T> Queue<T> {
    async fn put(&self, item: T) {
        loop {
            let mut g = self.inner.lock().await;   // yields, does not block
            if g.buf.len() < g.cap { g.buf.push_back(item); return; }
            drop(g);                               // never hold across the wait
            self.room.notified().await;
        }
    }
}
